module tb;
 logic clk=0,rst_n=1,start_a=0,start_b=0;
 wire [7:0] value_a,value_b;
 wire done_a,done_b;
 int a_completions=0,b_completions=0;
 always #5 clk=~clk;
 controller_probe dut(.*);
 always @(posedge clk) begin
  if(!rst_n) begin a_completions=0;b_completions=0;end
  else begin if(done_a)a_completions++;if(done_b)b_completions++;end
 end
 task tick; @(posedge clk);#1;endtask
 task pulse(input bit a,input bit b);
  @(negedge clk);start_a=a;start_b=b;
  @(negedge clk);start_a=0;start_b=0;
 endtask
 task both;
  pulse(1,1);repeat(12)tick;
  $display("EARLY a=%0d b=%0d a_done=%0d b_done=%0d",value_a,value_b,a_completions,b_completions);
  if(value_a!==1 || value_b!==1 || a_completions!=0 || b_completions!=1)
   $fatal(1,"independent short transaction must complete while long transaction waits");
  repeat(25)tick;
  if(a_completions!=1 || b_completions!=1)$fatal(1,"both transactions must complete once");
 endtask
 initial begin
  #2;rst_n=0;#10;rst_n=1;
  both;
  pulse(0,1);repeat(12)tick;
  if(value_a!==1 || value_b!==2 || a_completions!=1 || b_completions!=2)$fatal(1,"isolated short reactivation");
  pulse(1,0);repeat(30)tick;
  if(value_a!==2 || value_b!==2 || a_completions!=2 || b_completions!=2)$fatal(1,"isolated long reactivation");
  pulse(1,1);repeat(3)tick;
  @(negedge clk);rst_n=0;repeat(3)tick;
  if(value_a!==0 || value_b!==0)$fatal(1,"reset retained partial work");
  @(negedge clk);rst_n=1;
  both;
  $display("INDEPENDENT_CONTROLLER_PASS");$finish;
 end
 initial begin #10000;$fatal(1,"timeout");end
endmodule

module tb;
 logic clk=0,rst_n=1,start_a=0,start_b=0;
 wire [7:0] value_a,value_b;
 wire done_a,done_b;
 int a_completions=0,b_completions=0;
 always #5 clk=~clk;
 controller_probe dut(.*);
 always @(posedge clk) begin
  if(!rst_n) begin a_completions=0;b_completions=0;end
  else begin if(done_a)a_completions++;if(done_b)b_completions++;end
 end
 task tick; @(posedge clk);#1;endtask
 task activation(input int expected);
  @(negedge clk);start_a=1;
  @(negedge clk);start_a=0;
  repeat(24)tick;
  $display("CALL child=%0d parent=%0d parent_done=%0d child_done=%0d",value_a,value_b,a_completions,b_completions);
  if(value_a!==8'(expected) || value_b!==8'(expected) || a_completions!=expected || b_completions!=expected)
   $fatal(1,"blocking local call must execute each side once");
  repeat(8)tick;
  if(value_a!==8'(expected) || b_completions!=expected)$fatal(1,"held call start reexecuted callee");
 endtask
 initial begin
  #2;rst_n=0;#10;rst_n=1;
  activation(1);activation(2);
  @(negedge clk);start_a=1;
  @(negedge clk);start_a=0;
  repeat(3)tick;
  @(negedge clk);rst_n=0;repeat(3)tick;
  if(value_a!==0 || value_b!==0)$fatal(1,"reset retained partial work");
  @(negedge clk);rst_n=1;
  activation(1);
  $display("LOCAL_CONTROLLER_PASS");$finish;
 end
 initial begin #10000;$fatal(1,"timeout");end
endmodule
